run drill_tfidf "/c/Users/john/AppData/Local/Temp/claude/C--/a65df56e-768a-48c0-afa4-3bf9b0548cb5/scratchpad/dig/ws2.sel.txt" "Report the router rerank design in full: TF-IDF word+trigram centroids, floor 0.15 -> 0.25, exact file paths, commands, Hit@1/Hit@3 numbers before and after, and the user's decisions. Cite lines." --lines 1100-1350 --chunk 6000
export LR_TWEET=2000 LR_MAXTOK=1200
run plan_review "/c/Users/john/Documents/Tools/skilljepa/SELFIMPROVE_PLAN.md" "You are reviewing this plan for continuous self-improvement of a skill router that must end as a very small trainable model loaded on a GPU beside other small LLMs (mixture of models). List the 5 biggest gaps or risks (missing step, wrong order, unrealistic pass criterion, hardware/VRAM problem, data leakage between train/eval) and one concrete fix each. Cite lines. Max 1800 characters." --chunk 12000
export LR_TWEET=30000 LR_MAXTOK=7000
run nomatch_gen skills_index.txt "TASK (ignore the NONE rule and the 'answer only from text' rule for this task; do cite nothing): the text lists every skill of a solo developer (game modding of old PC/Saturn games, Rust/Bevy fan games, drawing, PC admin, local LLMs on 2 GPUs, decompiles, YouTube). Write 100 realistic prompts this user could type that match NONE of the listed skills (general coding questions, maths, cooking, emails, travel, unrelated tools, one-line chit-chat, Windows questions outside pc-troubleshooting). Output ONLY JSON lines, one per line: {\"prompt\": \"...\", \"why_none\": \"<=8 words\"}. Vary length 3-25 words, 1/3 in Brazilian Portuguese." --chunk 12000
run trace_pairs_draft trace_inputs.txt "TASK (ignore the NONE rule; output code only): write a complete Python 3.13 script skilljepa/trace_pairs.py. It reuses the join logic of ops/route_trace.py (import it or copy the join) to produce skilljepa/data/trace_pairs.jsonl, one line per routed prompt: {\"query\",\"sid\",\"t\",\"route_top\":[3 skills],\"conf\",\"class\": brief_only|full_read|miss|none+read, \"read_skill\", \"label\": skill actually read or route_top[0] for brief_only, \"reward\": +1 hit (brief_only/full_read with top skill), 0 none, -1 miss}. Flags --days N, --out PATH; prints counts per class and the number of rewarded rows; exits with 'STOP partial: <n> of 300' when fewer than 300 rewarded rows. Stdlib only, Windows paths via os.path.expanduser." --chunk 12000
run gpu_py_draft "/c/Users/john/Documents/Tools/llm/localread.py" "TASK (ignore the NONE rule; output code only): write a complete stdlib-only module Documents/Tools/llm/gpu.py lifted from this file: free_vram_mb(index), game_running() -> True if nvidia-smi --query-compute-apps lists a process under steamapps or games (then gpu 0 is off limits), pick_gpu(need_mb, prefer=None) -> index with most free VRAM that fits (never 0 while game_running), start_strata(model, port=None, gpu=None) using STRATA_CFG_GPU and CREATE_NO_WINDOW, wait for /health, stop_port(port) that kills the serve/server.py python whose command line holds that --port, and a CLI: py gpu.py free|pick 9500|start strata|stop 8090. Keep the constants verbatim." --lines 1-180 --chunk 12000
run eval_all_draft eval_inputs.txt "TASK (ignore the NONE rule; output code only): write a complete Python 3.13 script skilljepa/eval_all.py that runs the production router eval (ops/treeroute_eval.py, including --sid-only) and the skilljepa.py eval on the existing data/eval-*.json splits (prompt, session, time, prevskill variants) by importing or subprocess, collects Hit@1, Hit@3, abstain accuracy and latency per split into one dict, writes skilljepa/data/eval-<YYYYMMDD>.json and prints a markdown table; --compare PATH prints the delta against an older json. Reuse the functions you see; do not invent data formats: read them from the code shown." --chunk 12000
export LR_TWEET=300 LR_MAXTOK=350
run dig_ws1_a "/c/Users/john/AppData/Local/Temp/claude/C--/a65df56e-768a-48c0-afa4-3bf9b0548cb5/scratchpad/dig/ws1.sel.txt" "$Q" --lines 1-2500 --chunk 6000
